private void prepareValoriDatoBando(
        ActionRequest actionRequest,
        String rowIndexes,
        CodiceDatoBandoEnum codiceDatoBando,
        String keyValore,              // e.g., "disabilitaCampoOggetto"
        String keyIdValore,            // e.g., "idValoriDatoBandoDisabilitaCampoOggetto"
        List<Long> listaIdValoriDatiBando,
        List<ValoreDatoBando> listaValoriDatiBando,
        long idBando,
        String userFullName,
        long userId,
        long siteGroupId,
        long companyId
){
    try{
        DatoBando datoBando = datoBandoLocalService.findByCodice(codiceDatoBando.name());

        for (int i = 1; i <= Long.valueOf(rowIndexes); i++) {
            // Line 3772-3773: Read checkbox value and ID from request
            long valoreId = ParamUtil.getLong(actionRequest, keyIdValore + i);  // "idValoriDatoBandoDisabilitaCampoOggetto1"
            String valore = ParamUtil.getString(actionRequest, keyValore + i);  // "disabilitaCampoOggetto1"

            if(valore != null && !"".equals(valore)){
                // Line 3776-3785: Create or update ValoreDatoBando
                ValoreDatoBando valoreDatoBando = this.getValoriDatoBando(
                        datoBando.getDatoBandoId(),
                        valoreId,
                        valore.trim(),
                        idBando,
                        userFullName,
                        userId,
                        siteGroupId,
                        companyId
                );

                if(valoreDatoBando != null){
                    // Line 3788-3789: Add to lists
                    listaIdValoriDatiBando.add(valoreDatoBando.getValoreDatoBandoId());
                    listaValoriDatiBando.add(valoreDatoBando);
                }
            }
        }
    }
    catch(Exception e){
        throw new RuntimeException(e.getMessage(), e);
    }
}
```

