private ValoreDatoBando getValoriDatoBando(long datoBandoId, long valoreId, String valore, 
                                           long idBando, String userFullName, long userId, 
                                           long siteGroupId, long companyId){
    try{
        ValoreDatoBando valoreDatoBando = null;

        if(valoreId <= 0){
            // New ValoreDatoBando
            valoreDatoBando = valoreDatoBandoLocalService.createValoreDatoBando(CounterLocalServiceUtil.increment());
        }
        else{
            // Existing ValoreDatoBando
            valoreDatoBando = valoreDatoBandoLocalService.getValoreDatoBando(valoreId);
        }

        valoreDatoBando.setBandoId     (idBando);
        valoreDatoBando.setDatoBandoId (datoBandoId);
        valoreDatoBando.setValore      (valore);  // "true" or "false"
        valoreDatoBando.setGroupId     (siteGroupId);
        valoreDatoBando.setCompanyId   (companyId);
        valoreDatoBando.setUserId      (userId);
        valoreDatoBando.setUserName    (userFullName);

        return valoreDatoBando;
    }
    catch(Exception e){
        _log.error(e.getMessage(), e);
    }

    return null;
}
```

