private ValoreDatoBando getValoriDatoBando(long datoBandoId, long valoreId, String valore, long idBando, String userFullName, long userId, long siteGroupId, long companyId){
    try{
        ValoreDatoBando valoreDatoBando = null;

        if(valoreId <= 0){
            valoreDatoBando = valoreDatoBandoLocalService.createValoreDatoBando(CounterLocalServiceUtil.increment());
        }
        else{
            valoreDatoBando = valoreDatoBandoLocalService.getValoreDatoBando(valoreId);
        }

        valoreDatoBando.setBandoId     (idBando);
        valoreDatoBando.setDatoBandoId (datoBandoId);
        valoreDatoBando.setValore      (valore);
        valoreDatoBando.setGroupId     (siteGroupId);
        valoreDatoBando.setCompanyId   (companyId);
        valoreDatoBando.setUserId      (userId);
        valoreDatoBando.setUserName    (userFullName);

        return valoreDatoBando;
    }
    catch(Exception e){
        _log.error(e.getMessage(), e);
    }

    return null;
}

private void prepareValoriDatoBando(
        ActionRequest actionRequest,
        String rowIndexes,
        CodiceDatoBandoEnum codiceDatoBando,
        String keyValore,
        String keyIdValore,
        List<Long> listaIdValoriDatiBando,
        List<ValoreDatoBando> listaValoriDatiBando,
        long idBando,
        String userFullName,
        long userId,
        long siteGroupId,
        long companyId
){
    try{
        DatoBando datoBando = datoBandoLocalService.findByCodice(codiceDatoBando.name());

        for (int i = 1; i <= Long.valueOf(rowIndexes); i++) {

            long valoreId = ParamUtil.getLong(actionRequest, keyIdValore + i);
            String valore = ParamUtil.getString(actionRequest, keyValore + i);

            if(valore != null && !"".equals(valore)){
                ValoreDatoBando valoreDatoBando = this.getValoriDatoBando(
                        datoBando.getDatoBandoId(),
                        valoreId,
                        valore.trim(),
                        idBando,
                        userFullName,
                        userId,
                        siteGroupId,
                        companyId
                );

                if(valoreDatoBando != null){
                    listaIdValoriDatiBando.add(valoreDatoBando.getValoreDatoBandoId());
                    listaValoriDatiBando.add(valoreDatoBando);
                }
            }
        }
    }
    catch(Exception e){
        throw new RuntimeException(e.getMessage(), e);
    }
}

